SELECT pg_temp.update_local_seo('project', 'pl', '8bitjelly', $local_seo${"summary":"Strona stworzona specjalnie dla hobbistycznej grupy programistów gier komputerowych. Prowadzą tam bloga w którym dokumentują wszystkie poczynania odnośnie gier jakie tworzą ","data":{},"seo_title":"8BitJelly","seo_description":"Strona stworzona specjalnie dla hobbistycznej grupy programistów gier komputerowych. Prowadzą tam bloga w którym dokumentują wszystkie poczynania odnośnie gier jakie tworzą "}$local_seo$::jsonb, $local_seo${"summary":"Strona grupy tworzącej gry komputerowe, z blogiem do publikowania postępów prac i panelem do samodzielnego zarządzania treścią.","data":{"clientName":"8BitJelly","industry":"Tworzenie gier komputerowych","serviceSlugs":["strony-internetowe"],"caseStudy":{"challenge":"Grupa potrzebowała wspólnego miejsca do przedstawienia projektów i dzielenia się postępami prac nad grami.","solution":"Zaprojektowałem interfejs w Figma i wdrożyłem stronę w Nuxt oraz TypeScript. Panel Strapi pozwalał członkom grupy zarządzać treściami i publikować wpisy na blogu.","outcome":"Zespół otrzymał oficjalną stronę i kanał publikowania aktualności o grach. Treści bloga można było dodawać przez CMS, bez zmian w kodzie strony."}},"seo_title":"8BitJelly — strona z blogiem i CMS | Makoto","seo_description":"Strona grupy tworzącej gry komputerowe, z blogiem do publikowania postępów prac i panelem do samodzielnego zarządzania treścią."}$local_seo$::jsonb);

SELECT pg_temp.update_local_seo('project', 'pl', 'radec24', $local_seo${"summary":"Radec24 to firma która zajmuje się montażem sufitów napinanych. Mają świetną jakość swojej pracy.","data":{},"seo_title":"Radec24","seo_description":"Radec24 to firma która zajmuje się montażem sufitów napinanych. Mają świetną jakość swojej pracy."}$local_seo$::jsonb, $local_seo${"summary":"Strona firmy montującej sufity napinane: projekt identyfikacji, interfejsu oraz wdrożenie serwisu z panelem do edycji treści.","data":{"clientName":"Radec24","industry":"Montaż sufitów napinanych","serviceSlugs":["strony-internetowe"],"caseStudy":{"challenge":"Firma potrzebowała strony prezentującej ofertę oraz możliwości aktualizowania treści bez angażowania programisty przy każdej zmianie.","solution":"Przygotowałem logo i identyfikację wizualną, projekt interfejsu w Figma oraz wdrożenie w Nuxt i TypeScript. Strapi pełnił rolę panelu treści połączonego z aplikacją.","outcome":"Firma otrzymała spójny serwis i panel umożliwiający samodzielną edycję treści. Projekt objął identyfikację marki, interfejs i wdrożenie obu warstw aplikacji."}},"seo_title":"Radec24 — strona firmy usługowej | Makoto","seo_description":"Strona firmy montującej sufity napinane: projekt identyfikacji, interfejsu oraz wdrożenie serwisu z panelem do edycji treści."}$local_seo$::jsonb);

