SELECT pg_temp.update_local_seo('project', 'en', 'yescandles', $local_seo${"summary":"An online shop for people who value high-quality everyday items and scented candles.","data":{},"seo_title":"YesCandles","seo_description":"An online shop for people who value high-quality everyday items and scented candles."}$local_seo$::jsonb, $local_seo${"summary":"An online store for handmade candles and decorations, implemented with WordPress and WooCommerce, including products, payments and shipping.","data":{"clientName":"YesCandles","industry":"Candles and home decor","serviceSlugs":["online-stores"],"caseStudy":{"challenge":"The brand needed to launch online sales of candles and decorations with a complete purchase process.","solution":"I designed the interface in Figma, configured WordPress and WooCommerce and adapted the store to the brand. The implementation included products, payment gateways and shipping methods.","outcome":"The client received a store for presenting products and handling online purchases. Products and orders were managed in WooCommerce."}},"seo_title":"YesCandles — WooCommerce online store | Makoto","seo_description":"An online store for handmade candles and decorations, implemented with WordPress and WooCommerce, including products, payments and shipping."}$local_seo$::jsonb);

WITH created AS (
  INSERT INTO content_entries(kind, locale, slug, translation_group, title, summary, body, sections, data, status, seo_title, seo_description, source_key, published_at)
  VALUES ('article', 'pl', 'co-przygotowac-przed-zamowieniem-strony', 'guide:website-preparation', 'Co przygotować przed zamówieniem strony internetowej?', 'Lista materiałów i decyzji, które pomagają ustalić zakres, wycenę i sposób pracy nad stroną firmową.', $local_seo${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nie musisz mieć gotowych tekstów ani projektu, żeby zapytać o stronę. Najwięcej daje krótki opis firmy i tego, co ma zmienić nowa witryna. Czy klient ma zadzwonić, wysłać zapytanie, umówić wizytę czy kupić produkt? Odpowiedź porządkuje zakres znacznie lepiej niż lista stron, które podobają Ci się wizualnie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Opisz ofertę i odbiorcę"}]},{"type":"paragraph","content":[{"type":"text","text":"Wypisz usługi lub grupy produktów. Przy każdej dodaj, dla kogo jest przeznaczona i o co klient pyta przed zakupem. Jeśli działasz lokalnie, podaj rzeczywisty obszar obsługi. Firma z Inowrocławia, Torunia czy Bydgoszczy może obsługiwać klientów w mieście, w regionie albo zdalnie — na stronie powinno to być jednoznaczne."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Czym zajmuje się firma i kto korzysta z jej usług?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Które usługi są najważniejsze?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jakie pytania najczęściej pojawiają się przed zamówieniem?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gdzie faktycznie obsługujesz klientów?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Zbierz materiały, które już masz"}]},{"type":"paragraph","content":[{"type":"text","text":"Przygotuj logo w najlepszej dostępnej jakości, zdjęcia produktów lub wykonanych prac i istniejące opisy oferty. Nie musisz od razu porządkować wszystkiego. Warto jednak zaznaczyć, które materiały są aktualne i do których masz prawo publikacji. Zdjęcia z własnych realizacji zwykle pomagają lepiej zrozumieć usługę niż przypadkowe fotografie ze stocka."}]},{"type":"paragraph","content":[{"type":"text","text":"Jeśli chcesz pokazać opinię klienta, zachowaj jej treść, autora i źródło. Dane kontaktowe, nazwa firmy i informacje o sposobie obsługi powinny odpowiadać temu, co podajesz również w innych miejscach w internecie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Oddziel potrzebne funkcje od pomysłów na później"}]},{"type":"paragraph","content":[{"type":"text","text":"Formularz, rezerwacje, katalog produktów, sklep, konto klienta i integracja z CRM oznaczają różny zakres pracy. Opisz funkcję przez sposób użycia: kto z niej korzysta, jakie informacje wpisuje i co ma się wydarzyć dalej. To pozwala ocenić, czy wystarczy proste rozwiązanie, czy potrzebny jest osobny proces lub aplikacja."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jakie dane ma zbierać formularz i gdzie ma trafić wiadomość?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Czy potrzebujesz drugiego języka?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kto będzie zmieniać teksty, zdjęcia i ofertę?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Czy stronę trzeba połączyć z innym systemem?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Ustal, kto przygotuje treści"}]},{"type":"paragraph","content":[{"type":"text","text":"Teksty, tłumaczenia i zdjęcia mają wpływ na termin. W wiadomości zaznacz, co dostarczysz samodzielnie, a przy czym potrzebujesz pomocy. Jeżeli ofertę trzeba dopiero uporządkować, warto omówić to przed wyceną. Inny zakres ma przeniesienie gotowych materiałów, a inny opracowanie struktury i opisów od początku."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Przy przebudowie dołącz adres obecnej strony"}]},{"type":"paragraph","content":[{"type":"text","text":"Wskaż elementy, które chcesz zachować: opisy, blog, realizacje, formularze lub katalog. Napisz też, co dziś utrudnia pracę. Przed zmianą trzeba ustalić dostęp do domeny, hostingu i poczty oraz sposób przeniesienia treści. Nie wysyłaj haseł w pierwszym zapytaniu; na tym etapie wystarczy informacja, jakie konta i systemy posiadasz."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Krótka wiadomość wystarczy na początek"}]},{"type":"paragraph","content":[{"type":"text","text":"Możesz napisać: „Prowadzę firmę zajmującą się…, obsługuję…, potrzebuję strony, na której klient będzie mógł…. Mam logo i zdjęcia, ale potrzebuję pomocy z tekstami. Obecna strona to…”. Dodaj oczekiwany termin oraz budżet, jeśli został już określony. Taki opis pozwala zacząć od właściwych pytań."}]},{"type":"paragraph","content":[{"type":"text","text":"Sprawdź zakres tworzenia stron internetowych dla firm.","marks":[{"type":"link","attrs":{"href":"/pl/strony-internetowe"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Zobacz przykłady wykonanych realizacji.","marks":[{"type":"link","attrs":{"href":"/pl/work"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Prześlij opis swojego projektu.","marks":[{"type":"link","attrs":{"href":"/pl/kontakt"}}]}]}]}$local_seo$::jsonb, $local_seo$[]$local_seo$::jsonb, $local_seo${}$local_seo$::jsonb, 'published', 'Co przygotować przed zamówieniem strony internetowej? | Makoto', 'Cel strony, oferta, zdjęcia, teksty, funkcje i dostępy. Sprawdź, co przygotować przed rozmową o stronie dla Twojej firmy.', 'seed:guide:website-preparation:pl', now())
  ON CONFLICT DO NOTHING RETURNING *
)
INSERT INTO content_versions(entry_id, number, snapshot)
