WITH created AS (
  INSERT INTO content_entries(kind, locale, slug, translation_group, title, summary, body, sections, data, status, seo_title, seo_description, source_key, published_at)
  VALUES ('article', 'pl', 'jak-porownac-wyceny-strony-internetowej', 'guide:website-estimates', 'Jak porównać wyceny strony internetowej?', 'Co sprawdzić w zakresie projektu, treściach, CMS, utrzymaniu i przekazaniu strony, żeby porównywać rzeczywiście podobne oferty.', $local_seo${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dwie oferty opisane jako „strona firmowa” mogą obejmować zupełnie inną pracę. W jednej cenie są gotowe teksty i indywidualny projekt, w drugiej tylko wdrożenie dostarczonych materiałów. Zanim porównasz kwoty, sprawdź, co dokładnie otrzymasz i jakie koszty pojawią się po uruchomieniu."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Porównaj podstrony i funkcje"}]},{"type":"paragraph","content":[{"type":"text","text":"Sama liczba podstron nie opisuje złożoności projektu. Prosty opis usługi, katalog z filtrowaniem i panel klienta to różne zadania. W wycenie powinien być czytelny zakres: widoki, formularze, języki, integracje oraz sposób publikacji treści. Zwróć uwagę, czy oferta uwzględnia wersję mobilną i działanie elementów, a nie tylko ich wygląd."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jakie podstrony i funkcje obejmuje cena?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Które materiały przygotowuje wykonawca?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Czy w zakresie są integracje i przeniesienie danych?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Co jest opcją dodatkową i jak zostanie wycenione?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sprawdź sposób przygotowania projektu"}]},{"type":"paragraph","content":[{"type":"text","text":"Adaptacja istniejącego szablonu i indywidualny projekt interfejsu mogą być właściwymi rozwiązaniami, ale powinny być opisane wprost. Zapytaj, co dostajesz do akceptacji, kiedy przekazujesz uwagi i jakie poprawki obejmuje ustalony zakres. Przy istniejącej identyfikacji ustal również, czy logo, typografia i materiały zostaną wykorzystane w projekcie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Teksty i zdjęcia też są częścią pracy"}]},{"type":"paragraph","content":[{"type":"text","text":"Wyjaśnij, czy dostarczasz gotowe treści, czy potrzebujesz pomocy w ich uporządkowaniu. Sprawdź zakres redakcji, tłumaczeń i przygotowania zdjęć. Przy stronie lokalnej ważne są prawdziwe przykłady realizacji, aktualne dane firmy i jasny obszar obsługi. Ich zebranie zajmuje czas, który warto uwzględnić w harmonogramie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Zapytaj, co samodzielnie zmienisz w CMS"}]},{"type":"paragraph","content":[{"type":"text","text":"Hasło „panel do edycji” nie mówi jeszcze, które elementy są dostępne. Poproś o listę: teksty oferty, zdjęcia, realizacje, blog, dane kontaktowe czy wersje językowe. Zapytaj o sposób dodawania nowych treści i materiały pokazujące obsługę. Dobrze dobrany panel odpowiada codziennej pracy firmy, a jego zakres powinien być znany przed wdrożeniem."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Rozdziel wdrożenie i koszty utrzymania"}]},{"type":"paragraph","content":[{"type":"text","text":"Domena, hosting, poczta, płatne usługi i opieka mogą być rozliczane osobno. Poproś o wskazanie, kto zakłada i opłaca konta, jak odnawiane są usługi i kto otrzymuje dostępy. Zapytaj również o aktualizacje, kopie zapasowe i procedurę zgłoszenia usterki. Zakres utrzymania dobiera się do konkretnego środowiska; warto mieć go zapisany."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jakie opłaty są jednorazowe, a jakie cykliczne?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Na kogo zarejestrowana będzie domena i konta usług?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kto odpowiada za kopie, aktualizacje i odtwarzanie strony?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Jak wyceniane będą późniejsze zmiany?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Przy przebudowie uwzględnij przeniesienie"}]},{"type":"paragraph","content":[{"type":"text","text":"Jeśli strona już działa, wycena powinna określać, które treści i funkcje zostaną przeniesione. Warto omówić obecne adresy podstron, domenę, pocztę i formularze. Zmiana wyglądu jest jednym z etapów; równie ważny jest plan uruchomienia i sprawdzenia działania po przeniesieniu."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Termin powinien wynikać z zakresu"}]},{"type":"paragraph","content":[{"type":"text","text":"Zapytaj, kiedy wykonawca potrzebuje materiałów i kto akceptuje etapy projektu. Oczekiwany termin można ocenić dopiero razem z funkcjami, przygotowaniem treści i integracjami. Przed wyborem warto zobaczyć realizacje podobne do Twojej potrzeby i dowiedzieć się, jaki zakres wykonała osoba przedstawiająca ofertę."}]},{"type":"paragraph","content":[{"type":"text","text":"Najwygodniej porównywać oferty w krótkiej tabeli: zakres, materiały, funkcje, edycja, termin, wdrożenie i utrzymanie. Jeżeli przy którejś pozycji brakuje informacji, dopytaj przed podjęciem decyzji. Dzięki temu cena odnosi się do konkretnego projektu."}]},{"type":"paragraph","content":[{"type":"text","text":"Poznaj zakres projektowania i tworzenia stron firmowych.","marks":[{"type":"link","attrs":{"href":"/pl/strony-internetowe"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Sprawdź ofertę opieki technicznej nad stroną.","marks":[{"type":"link","attrs":{"href":"/pl/opieka-techniczna"}}]}]},{"type":"paragraph","content":[{"type":"text","text":"Opisz projekt, który chcesz wycenić.","marks":[{"type":"link","attrs":{"href":"/pl/kontakt"}}]}]}]}$local_seo$::jsonb, $local_seo$[]$local_seo$::jsonb, $local_seo${}$local_seo$::jsonb, 'published', 'Jak porównać wyceny strony internetowej dla firmy? | Makoto', 'Porównaj zakres, projekt graficzny, treści, CMS, hosting i opiekę. Lista pytań przed wyborem wykonawcy strony internetowej.', 'seed:guide:website-estimates:pl', now())
  ON CONFLICT DO NOTHING RETURNING *
)
